def cancel_duplicate_active_assignments(apps, schema_editor):
    """Keep at most one ACTIVE assignment per work item before adding the rule.

    Existing installations may contain duplicates created before the service
    layer enforced single-active assignments.  The newest assignment wins; the
    older duplicates are marked CANCELLED instead of deleted so the audit trail
    survives.
    """
    WorkAssignment = apps.get_model('workload', 'WorkAssignment')
    duplicates = (
        WorkAssignment.objects.filter(status='ACTIVE')
        .values('work_item_id')
        .annotate(total=Count('id'))
        .filter(total__gt=1)
    )
    for row in duplicates:
        keep_id = (
            WorkAssignment.objects.filter(
                work_item_id=row['work_item_id'],
                status='ACTIVE',
            )
            .order_by('-assigned_at', '-id')
            .values_list('id', flat=True)
            .first()
        )
        WorkAssignment.objects.filter(
            work_item_id=row['work_item_id'],
            status='ACTIVE',
        ).exclude(pk=keep_id).update(status='CANCELLED')


